package br.com.archlab.simulation.core.v3;
import org.junit.jupiter.api.Test;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static br.com.archlab.simulation.core.v3.SynchronousExecutionV3Test.*;import static br.com.archlab.simulation.core.v3.AsynchronousExecutionV3Test.reference;import static br.com.archlab.simulation.core.v3.AsynchronousExecutionV3Test.groups;import static br.com.archlab.simulation.core.v3.AsynchronousExecutionV3Test.inject;import static br.com.archlab.simulation.core.v3.ArchitectureV3.*;import static br.com.archlab.simulation.core.v3.ExecutionPlanV3.*;import br.com.archlab.simulation.core.v3.ExecutionPlanV3.Process;import static br.com.archlab.simulation.core.v3.DeterministicSchedulerV3.Phase.*;
/** Coverage is measured from dispatched production journals, not handler registration. */
class ExecutionMatrixV3Test {
    private final Set<SimulationEventV3.Type> events=EnumSet.noneOf(SimulationEventV3.Type.class);private final Set<String> steps=new TreeSet<>();
    void check(SimulationEngineV3 engine){for(int i=0;i<7 && engine.step();i++){}var halfway=engine.checkpoint();var restored=SimulationEngineV3.resume(halfway);var finished=engine.run();assertEquals(finished,restored.run());var replayed=AtomicDispatcherV3.replay(finished.initial(),finished.current().journal());assertEquals(finished.current(),replayed);var projection=ResultProjectorV3.project(finished);assertEquals(projection.finalState(),PublicReplayV3.replay(projection.initialState(),projection.deltas(),finished.current().trace(),projection.finalState().virtualTimeMs()));
        for(var c:finished.current().journal())events.add(c.event().payload().eventType());for(var run:engine.control().runs().values()){var activation=engine.control().activations().get(run.activation());finished.request().architecture().executionPlans().stream().filter(plan->plan.operationId().equals(activation.operationId())).flatMap(plan->plan.steps().stream()).filter(step->step.id().equals(run.step())).forEach(step->steps.add(step.getClass().getSimpleName()));}}
    SimulationRequestV3 replace(SimulationRequestV3 r,List<Resource> resources,List<ExecutionPlanV3> plans,List<InitialStateV3> initial){var a=r.architecture();return new SimulationRequestV3(new ArchitectureV3(a.id(),a.schemaVersion(),a.components(),resources,a.endpoints(),a.operations(),a.relations(),plans),new SimulationRequestV3.Scenario(r.scenario().id(),r.scenario().entry(),initial,r.scenario().parameters()),r.options());}
    @Test void dispatchesAll32EventsAndAllNineStepsWithRestartAndReplayProof(){
        check(new SimulationEngineV3(reference(AwaitPublish.NONE,Map.of())));check(new SimulationEngineV3(reference(AwaitPublish.CONSUMER_ACK,Map.of("ackTimeoutMs",n(20),"maxDeliveryAttempts",n(2),"redeliveryDelayMs",n(5)))));check(new SimulationEngineV3(reference(AwaitPublish.CONSUMER_ACK,Map.of("ttlMs",n(50)))));
        var r=reference(AwaitPublish.NONE,Map.of());check(new SimulationEngineV3(new SimulationRequestV3(r.architecture(),r.scenario(),new SimulationRequestV3.Options(7,SimulationRequestV3.CompletionMode.UNTIL_HORIZON,150L))));
        check(new SimulationEngineV3(groups(JoinPolicy.ALL,RemainingPolicy.CONTINUE,null,null,-10,30)));check(new SimulationEngineV3(groups(JoinPolicy.ANY,RemainingPolicy.CANCEL_REQUEST,null,null,10,30)));check(new SimulationEngineV3(fixture(40L,null,false,true)));check(new SimulationEngineV3(fixture(null,10L,false,true)));
        var policy=fixture(null,200L,false,true);var resources=new ArrayList<Resource>();for(var resource:policy.architecture().resources())resources.add(resource.id().equals(id("call-policy"))?new Resource(resource.id(),resource.typeId(),resource.ownerId(),Map.of("timeoutMs",n(200),"attemptTimeoutMs",n(5),"maxAttempts",n(2),"retryDelayMs",n(3))):resource);check(new SimulationEngineV3(replace(policy,resources,policy.architecture().executionPlans(),List.of())));
        check(inject(new SimulationEngineV3(policy),0,ENVIRONMENT_CHANGE,new SimulationEventV3.PolicyTransitionDue(id("call-policy"),id("policy-change"),id("DISABLED"))));
        var basic=fixture(null,null,false,true);var unavailable=replace(basic,basic.architecture().resources(),basic.architecture().executionPlans(),List.of(new InitialStateV3.Resource(id("db-pool"),false)));check(inject(new SimulationEngineV3(unavailable),40,ENVIRONMENT_CHANGE,new SimulationEventV3.ResourceStateChangeDue(id("db-pool"),id("make-available"),id("AVAILABLE"))));
        resources=new ArrayList<Resource>();for(var resource:basic.architecture().resources())resources.add(new Resource(resource.id(),resource.typeId(),resource.ownerId(),Map.of("capacity",n(0),"waitTimeoutMs",n(5))));check(new SimulationEngineV3(replace(basic,resources,basic.architecture().executionPlans(),List.of())));
        var failed=new SimulationEngineV3(basic);while(failed.checkpoint().current().agenda().pending().stream().noneMatch(e->e.payload() instanceof SimulationEventV3.MessageArrivalDue))assertTrue(failed.step());var arrival=failed.checkpoint().current().agenda().pending().stream().filter(e->e.payload() instanceof SimulationEventV3.MessageArrivalDue).map(e->(SimulationEventV3.MessageArrivalDue)e.payload()).findFirst().orElseThrow();check(inject(new SimulationEngineV3(basic),5,DELIVERY_OR_COMPLETION,new SimulationEventV3.MessageDeliveryFailureDue(arrival.messageId(),arrival.attemptId(),id("INJECTED_TRANSPORT_FAILURE"),arrival.pathSegmentId())));
        var old=basic.architecture().executionPlans().getFirst();var planSteps=new ArrayList<Step>(old.steps());planSteps.add(new Condition(id("condition"),new Compare(Comparison.EQ,new Literal(true),new Literal(true)),id("pre"),id("fail"),id("fail")));var conditionPlan=new ExecutionPlanV3(old.id(),old.operationId(),id("condition"),old.limits(),planSteps);check(new SimulationEngineV3(replace(basic,basic.architecture().resources(),List.of(conditionPlan),List.of())));
        assertEquals(EnumSet.allOf(SimulationEventV3.Type.class),events,"Every event must actually dispatch");assertEquals(Set.of("Process","Call","Publish","Condition","Fork","Join","Delay","Complete","Fail"),steps,"Every step must actually execute");
    }
}
